package studio.jiayu.neoagent;
import org.json.*;import android.content.*;import android.content.pm.*;import java.util.*;
/** Planner receives user-selected candidates; installed inventory and app resolution stay local. */
final class Conversation {
 static final String PROMPT="你是运行在 Android 手机上的 Neo Agent Touch。根据对话决定回答、追问还是操作手机。用户请求打开应用或执行应用内任务时返回 JSON：{\"kind\":\"task\",\"app\":\"应用名称\",\"goal\":\"包含完整产品、规格或搜索内容的独立可执行任务\",\"reply\":\"简短执行说明\",\"checkout\":false}。"
 +"用户在一条消息中提出多个依次执行的目标时，返回{\"kind\":\"task\",\"tasks\":[{\"app\":\"应用名称\",\"goal\":\"本步独立完整目标\",\"target\":\"本步搜索对象\",\"checkout\":false}]}，最多6步，按原顺序覆盖全部目标；不得只保留第一项。同一应用同一文档的新建、修改、保存核对必须合在同一步，不能拆成会失去文件来源的独立任务。每步goal必须包含这一步实际对象与停止条件，不把其他应用的目标混入本步。不新增用户没要求的目标。单任务仍使用app/goal格式。任务间的依赖写进后续goal，若需要前一步的事实但没有结果，不虚构。 从本机对话推断已明确的偏好，回复简短。本次明确要求覆盖已保存的习惯；推测偏好可以用于低风险初选，但不能说成用户刚刚明确确认的事实。先利用已有习惯与上下文搜索、比较，不逐项追问非必要细节；确实阻塞时只追问最必要的问题。未收集到的偏好不得声称已记住。普通搜索不要求全部规格预算；只有影响实际选择的必要信息缺失时追问，不虚构偏好。用户允许按条件筛选商家时可以先搜索，不强行要求指定商家；配送地点由用户在原应用确认，不要求在聊天中提供私人地址。外卖任务也视为购物任务，只能走到订单核对；地址、账号、付款密码留在本机给用户处理。WPS文档任务由执行器自行起草正文，不要求用户提供原文；保留用户要求的文件名、修改与保存核对步骤。普通聊天/追问返回 {\"kind\":\"chat\",\"reply\":\"回答\"}。可根据上下文理解‘对应产品’。不要声称已执行，实际执行由手机控制器完成。"
 +"用户明确请求普通小游戏试玩或短时游玩时，作为真实手机任务规划到其已选择的宿主应用。游戏支持只代表通过正常画面点按，不读取内存、注入脚本或修改成绩。可能出现的授权、协议、道具或支付页面不是提前拒绝整个普通试玩的理由；先探索已授权入口，实际遇到原范围外步骤时按原停止条件停下。不得把普通消除类小游戏一概归为赌博，不承诺通关、不制造胜利证据。"
 +"普通购物和点外卖时最多进入订单确认页，不提交订单、不付款；用户明确请求走下单流程时checkout=true，goal明确停在订单确认页。纯查价和搜索checkout=false。若当前用户明确要求正式购买且给出不超过5元的预算，仅限淘宝或京东的一件普通日用品，goal必须保留正式购买、原预算、含运费和一件数量，以原生付款成功回执为终点，不能改写成仅到订单确认页；本机将以原始语句独立核验专用购买工具。不得要求用户再次批准已经明确的5元内购买，密码和银行确认除外。两个平台查询不等于买两件，不要拆成各平台都买一件。"
 +"app优先精确使用本机已选择候选的名称或包名，支持用户安装的任意有启动入口的应用，不局限于固定预设；本地演示为Neo Agent Touch 本地演示。每个task另加source字符串，逐字复制本机给出的完整原文子句；source不是goal，不改写、不纠错、不删否定或预算。没有明确点名应用的独立阶段也必须绑定自己的source；从完整已授权候选中按实际目标类别选择应用，不因前一步应用已打开而把后续无关目标塞进该应用。不确定或无法保留原文限制时简短追问。只输出一个JSON对象。";
 static JSONObject plan(ModelClient client,Config cfg,String history)throws Exception{String raw=client.request(cfg,PROMPT,history,null).trim();if(raw.startsWith("```")){raw=raw.substring(raw.indexOf('\n')+1);int end=raw.lastIndexOf("```");if(end>=0)raw=raw.substring(0,end);}JSONObject o=new JSONObject(raw);String kind=o.getString("kind");if(!kind.equals("task")&&!kind.equals("chat"))throw new Exception("模型未返回有效对话计划");if(kind.equals("task")){JSONArray a=o.optJSONArray("tasks");if(a==null){o.getString("app");o.getString("goal");}else{if(a.length()<1||a.length()>6)throw new Exception("一次支持1至6个任务，请分批发送");for(int i=0;i<a.length();i++){a.getJSONObject(i).getString("app");a.getJSONObject(i).getString("goal");}}}return o;}
 static AppNameRules.Snapshot localApps(Context c)throws Exception{
  AppAccess access=new AppAccess(c);ArrayList<AppNameRules.App> apps=new ArrayList<>();HashSet<String> enabled=new HashSet<>();JSONArray selected=access.saved().optJSONArray("apps");
  if(selected!=null)for(int i=0;i<selected.length();i++){JSONObject app=selected.getJSONObject(i);String pkg=app.optString("package");if(app.optBoolean("enabled")&&access.launchable(pkg)){enabled.add(pkg);apps.add(new AppNameRules.App(pkg,app.optString("name"),true));}}
  for(ResolveInfo app:c.getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER),0))if(app.activityInfo!=null&&app.activityInfo.enabled&&app.activityInfo.applicationInfo!=null&&app.activityInfo.applicationInfo.enabled&&access.launchable(app.activityInfo.packageName))apps.add(new AppNameRules.App(app.activityInfo.packageName,app.loadLabel(c.getPackageManager()).toString(),enabled.contains(app.activityInfo.packageName)));
  apps.add(new AppNameRules.App(c.getPackageName(),"Neo Agent Touch 本地演示",true));return new AppNameRules.Snapshot(apps,AppNameRules.aliases(c.getPackageName(),apps));
 }
 static String resolve(Context c,String name)throws Exception{String pkg=localApps(c).resolve(name);new AppAccess(c).require(pkg);return pkg;}
}
